INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'ro-voluntary', id, '2021-11-01', 1, 'https://mfinante.gov.ro/en/web/efactura/informatii-tehnice' FROM countries WHERE name_en = 'Romania';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ro-voluntary', 'en', 'RO e-Factura opens for voluntary use', 'The platform opened for voluntary registration ahead of any legal mandate, giving early-adopting businesses and public bodies time to test integration.', '[]');
INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'ro-b2g', id, '2022-07-01', 1, 'https://mfinante.gov.ro/en/web/efactura/informatii-tehnice' FROM countries WHERE name_en = 'Romania';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ro-b2g', 'en', 'B2G e-invoicing becomes mandatory', 'Public contracting authorities in scope of Law 199/2020 (transposing EU Directive 2014/55/EU) must accept and process EN 16931-compliant structured invoices for public procurement above EU thresholds.', '[]');
INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'ro-law296', id, '2024-01-01', 1, 'https://mfinante.gov.ro/en/web/efactura/informatii-tehnice' FROM countries WHERE name_en = 'Romania';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ro-law296', 'en', 'Law 296/2023 establishes mandatory B2B e-invoicing', 'B2B e-reporting obligations begin for taxable persons established in Romania (and non-established VAT-registered entities), operating under the Government Ordinance 120/2021 framework and RO_CIUS technical specification (MF Order 1366/2021).', '[]');
INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'ro-established', id, '2024-07-01', 1, 'https://mfinante.gov.ro/en/web/efactura/informatii-tehnice' FROM countries WHERE name_en = 'Romania';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ro-established', 'en', 'RO e-Factura clearance model mandatory for B2B/B2G (in force since Jul 2024)', 'Romania runs a centralised clearance (CTC) model: B2B and B2G invoices must be validated and digitally sealed by ANAF via RO e-Factura before they carry legal effect. B2C reporting followed from January 2025.', '["Confirm registration on RO e-Factura and generation of RO_CIUS-compliant XML invoices", "Transmission deadline is 5 working days from issuance (tightened from 5 calendar days in Jan 2026)"]');
INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'ro-b2c', id, '2025-01-01', 1, 'https://mfinante.gov.ro/en/web/efactura/informatii-tehnice' FROM countries WHERE name_en = 'Romania';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ro-b2c', 'en', 'B2C reporting joins the mandate', 'Regular B2C invoices must also be reported via RO e-Factura in RO_CIUS XML format. Point-of-sale tax receipts and one-off individual transactions remain exempt.', '[]');
INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'ro-nonvat-register', id, '2026-06-01', 0, 'https://mfinante.gov.ro/en/web/efactura/informatii-tehnice' FROM countries WHERE name_en = 'Romania';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ro-nonvat-register', 'en', 'Register extended to non-VAT-registered entities', 'The mandatory RO e-Invoice Register now also covers associations, foundations and non-profits not registered for VAT, individual farmers under the special agricultural regime, and sole traders identified by personal ID number (CNP).', '[]');
INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'ro-sme', id, '2026-07-01', 0, 'https://mfinante.gov.ro/en/web/efactura/informatii-tehnice' FROM countries WHERE name_en = 'Romania';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ro-sme', 'en', 'Full enforcement extends to small taxpayers (<€500,000 turnover)', 'Following a confirmed delay, small taxpayers with turnover below €500,000 become fully subject to e-Factura enforcement and penalties, on the same footing as larger businesses.', '["Standardise client addresses and country/ISO codes ahead of the deadline", "Confirm your invoicing tool applies the 5-working-day transmission rule"]');
